    vector<vector<long long>> ranges(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> ranges[i][j];
        }
    }

    sort(ranges.begin(), ranges.end());
    long long total = 0, curStart = ranges[0][0], curEnd = ranges[0][1];
    for (long long i = 1; i < n; i++) {
        long long s = ranges[i][0], e = ranges[i][1];
        if (s <= curEnd) {
            curEnd = max(curEnd, e);
        } else {
            total += curEnd - curStart;
            curStart = s;
            curEnd = e;
        }
    }
    total += curEnd - curStart;
    cout << total << "\n";

