import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] ranges = new long[(int) n][2];
        for (int i = 0; i < ranges.length; i++) {
            for (int j = 0; j < ranges[i].length; j++) {
                ranges[i][j] = Long.parseLong(next());
            }
        }

        long[] keys = new long[(int) n];
        for (int i = 0; i < n; i++) keys[i] = ranges[i][0] * 65536L + i;
        Arrays.sort(keys);
        int first = (int) (keys[0] % 65536L);
        long total = 0, curStart = ranges[first][0], curEnd = ranges[first][1];
        for (int t = 1; t < n; t++) {
            int i = (int) (keys[t] % 65536L);
            long s = ranges[i][0], e = ranges[i][1];
            if (s <= curEnd) {
                curEnd = Math.max(curEnd, e);
            } else {
                total += curEnd - curStart;
                curStart = s;
                curEnd = e;
            }
        }
        total += curEnd - curStart;
        System.out.println(total);
    }
}
